import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import { ThemeProvider, createTheme } from "@mui/material/styles";
import CssBaseline from "@mui/material/CssBaseline";
import Box from "@mui/material/Box";

// Компоненты
import Navbar from "./components/Navbar";
import Dashboard from "./pages/Dashboard";
import Leaderboard from "./pages/Leaderboard";
import Profile from "./pages/Profile";
import Referral from "./pages/Referral";

// Создаем тему в стиле Google Fit (приблизительно)
const theme = createTheme({
  palette: {
    mode: "dark", // Устанавливаем темную тему
    primary: {
      main: "#81D4FA", // Светло-голубой для основного цвета (примерно как на скриншоте)
      light: "#B0E5FF",
      dark: "#4BA3C7",
      contrastText: "#000000", // Черный текст на светлом фоне
    },
    secondary: {
      main: "#A5D6A7", // Светло-зеленый для вторичного цвета
      light: "#D7FFD9",
      dark: "#75A478",
      contrastText: "#000000", // Черный текст на светлом фоне
    },
    error: {
      main: "#EF9A9A", // Красный для ошибок
      light: "#FFCDD2",
      dark: "#D32F2F",
      contrastText: "#000000",
    },
    warning: {
      main: "#FFD54F", // Желтый для предупреждений
      light: "#FFFF81",
      dark: "#FFB300",
      contrastText: "#000000",
    },
    info: {
      main: "#81D4FA", // Информационный цвет - как primary
      light: "#B0E5FF",
      dark: "#4BA3C7",
      contrastText: "#000000",
    },
    success: {
      main: "#A5D6A7", // Цвет успеха - как secondary
      light: "#D7FFD9",
      dark: "#75A478",
      contrastText: "#000000",
    },
    background: {
      default: "#121212", // Очень темный фон
      paper: "#1E1E1E", // Чуть более светлый фон для карточек и элементов
    },
    text: {
      primary: "#FFFFFF", // Белый текст на темном фоне
      secondary: "rgba(255, 255, 255, 0.7)", // Светло-серый текст
    },
  },
  typography: {
    fontFamily: '"Roboto", "Arial", sans-serif', // Google Fit использует Roboto
    h4: {
      fontSize: "2rem", // Немного крупнее заголовки
      fontWeight: 500,
    },
    body2: {
      fontSize: "0.875rem", // Меньший текст для подписей
    },
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 20, // Более скругленные кнопки
          textTransform: "none",
          boxShadow: "none", // Без тени по умолчанию
        },
      },
    },
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 8, // Скругленные углы у карточек
          boxShadow: "0 2px 4px rgba(0,0,0,0.3)", // Легкая тень для темной темы
        },
      },
    },
    MuiCircularProgress: {
      styleOverrides: {
        root: {
          // Стиль для прогресса, можно доработать позже
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          borderRadius: 8,
          boxShadow: "0 2px 4px rgba(0,0,0,0.3)",
        },
      },
    },
  },
});

function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Router basename="/step-tracker">
        <Box
          sx={{ display: "flex", flexDirection: "column", minHeight: "100vh" }}
        >
          <Navbar />
          <Box component="main" sx={{ flexGrow: 1, p: 3 }}>
            <Routes>
              <Route path="/" element={<Dashboard />} />
              <Route path="/leaderboard" element={<Leaderboard />} />
              <Route path="/profile" element={<Profile />} />
              <Route path="/referral" element={<Referral />} />
            </Routes>
          </Box>
        </Box>
      </Router>
    </ThemeProvider>
  );
}

export default App;
